export const DEFAULT_COLUMN_CALCULATION = `(function calculatedFieldValue(current) {

	// Add your code here
	return '';  // return the calculated value

})(current);`

export function addFieldsToColumn(
    fields: { name: string; table: string; display: boolean },
    column: CallExpressionShape
) {
    const additionalFields = Shape.from(column, fields).asObject()

    return new CallExpressionShape({
        source: column.getSource(),
        callee: column.getCallee(),
        args: [column.getArgument(0).asObject().merge(additionalFields)],
    })
}

export function getDefaultMaxLength(columnType: string | undefined): number {
    switch (columnType) {
        case 'conditions':
        case 'glide_list':
        case 'json':
        case 'name_values':
        case 'multi_two_lines':
            return 4000
        case 'template_value':
            return 65000
        case 'script':
            return 8000
        case 'html':
            return 65536
        case 'decimal':
            return 20
        case 'float':
            return 15
        case 'domain_id':
        case 'document_id':
        case 'reference':
        case 'GUID':
            return 32
        case 'string_full_utf8':
        case 'domain_path':
        case 'user_roles':
        case 'password2':
        case 'email':
            return 255
        case 'url':
        case 'records':
            return 1024
        case 'table_name':
        case 'field_name':
            return 80
        case 'glide_duration':
            return 20
        case 'glide_time':
            return 8
        case 'field_list':
        case 'approval_rules':
            return 1024
        case 'slushbucket':
            return 4000
        default:
            /**
             * For types mentioned below it default to 40 on instance
             * boolean | integer | image | choice | radio | sys_class_name | translated_field | translated_text | version | glide_date | glide_date_time | calendar_date_time
             * datetime | due_date | integer_date | schedule_date_time | date | generic
             *
             * TODO::We need to request max_length from user for string column type because its mandatory on instance.
             */
            return 40
    }
}
